const arr = JSON.parse($input.first().json.output);  // 这是 10 个 segment 的数组

const results = [];

for (const seg of arr) {
  const section = seg.section;
  const text = seg.script;
  const prompt =
    seg.voice_note ||
    "Speak like a calm, friendly English podcast for beginner learners.";

  let speakerVoiceConfigs;

  if (section === "core_content_1") {
    // Tom & Anna
    speakerVoiceConfigs = [
      { speakerAlias: "Tom",  speakerId: "Schedar" },
      { speakerAlias: "Anna", speakerId: "Zephyr" },
    ];
  } else {
    // 默认 Jordan & Riley
    speakerVoiceConfigs = [
      { speakerAlias: "Jordan", speakerId: "Achird" },
      { speakerAlias: "Riley",  speakerId: "Kore"   },
    ];
  }

  const ttsBody = {
    input: { prompt, text },
    voice: {
      languageCode: "en-US",
      modelName: "gemini-2.5-pro-tts",
      multiSpeakerVoiceConfig: { speakerVoiceConfigs },
    },
    audioConfig: {
      audioEncoding: "LINEAR16",
      sampleRateHertz: 24000,
    },
  };

  results.push({
    json: {
      script: seg.script,
      voice_note: seg.voice_note,
      order: seg.order,
      section: seg.section,
      ttsBody,
    },
  });
}

return results;

// 1) 拿到所有上游 items
const items = $input.all();

// 2) 把每个 item.json.output 解析并合并
let merged = [];

for (const item of items) {
  const raw = item.json.output;
  if (!raw) continue;

  // output 可能是 string 也可能已经是 array
  let arr;
  if (typeof raw === 'string') {
    try {
      arr = JSON.parse(raw);   // "[{...},{...}]" -> [{...},{...}]
    } catch (e) {
      continue; // 爛資料就直接跳過
    }
  } else if (Array.isArray(raw)) {
    arr = raw;
  } else {
    continue;
  }

  if (Array.isArray(arr)) {
    merged = merged.concat(arr);
  }
}

// 3) 按 order 排序（如果有）
merged.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

// 4) n8n 規則：json 必須是「物件」，不能直接是 array
// 所以用一個 key 把 array 包起來，例如 merged
return [
  {
    json: {
      merged,   // 這裡就是 10 個 {script, voice_note, order, section}
    },
  },
];

